"risiken": "Hauttoxizität bei Langzeit-Gabe in Erstlinie; Resistenzen; Konkurrenz durch eigene Kombi-Partner und andere Pan-RAS-Inhibitoren; Kostenbasis.",
"begruendung": "Daraxonrasib ist eines der stärksten Onkologie-Assets des Jahrzehnts; nach der PDAC-Zulassung bestimmen NSCLC (2027) und Erstlinie PDAC (2028) das Umsatzpotenzial. Hohe Zulassungswahrscheinlichkeit für die Erweiterungen; Kursrisiko eher Bewertung als Datenlage.",
"kosten_jahr_usd": 300000,
